    {
      "id": "BR-10",
      "name": "贡献与创新",
      "maximum": 10,
      "strong_anchor": "与既有工作的差异明确，并有证据验证新增价值",
      "adequate_anchor": "可信的增量或组合贡献，独立新增能力验证有限"
